80	    /** Change a draft claim's amount, date and note; a blank date takes the sheet's today. A claim that
81	     *  is no longer a draft is refused: to change an open claim, void it and add a new one. */
82	    @Transactional
83	    public Claim update(String sheetId, String user, long id, BigDecimal amount, LocalDate date, String note,
84	            String corrects) {
85	        Claim claim = claims.findForUpdate(id, sheetId)
86	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
87	        LocalDate dated = dateOr(sheetId, date);
88	        refuseIfClosed(sheetId, claim.getDate());
89	        refuseIfClosed(sheetId, dated);
90	        if (claim.getStatus() != ClaimStatus.DRAFT) {
91	            throw new ResponseStatusException(HttpStatus.CONFLICT,
92	                    "A " + claim.getStatus() + " claim cannot be edited; only a DRAFT can.");
93	        }
94	        refuseIfRetired(person(sheetId, claim.getPersonId()), dated);
95	        refuseIfNotCorrecting(sheetId, claim.getPersonId(), amount, corrects);
96	        Rollup.Snapshot before = rollup.snapshot(sheetId);
97	        claim.set(amount, dated, noteOf(note), corrects);
98	        Claim saved = claims.saveAndFlush(claim);
99	        recordChange("CLAIM_EDITED", user, person(sheetId, saved.getPersonId()), saved);
100	        rollup.recordChanges(user, before);
101	        return saved;
102	    }
