104	    /** Move a claim to a new status; a change its status does not allow is refused, as is settling
105	     *  by the user who opened the claim. A clerk's settling of a claim whose due is above the sheet's
106	     *  clerk limit leaves it PENDING for a steward to approve (a due of n/a is within any limit; a
107	     *  steward settles anything). */
108	    @Transactional
109	    public Claim changeStatus(String sheetId, String user, long id, ClaimStatus next) {
110	        Claim claim = claims.findForUpdate(id, sheetId)
111	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
112	        refuseIfClosed(sheetId, claim.getDate());
113	        if (!claim.getStatus().canBecome(next)) {
114	            throw new ResponseStatusException(HttpStatus.CONFLICT,
115	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
116	        }
117	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
118	            throw new ResponseStatusException(HttpStatus.CONFLICT,
119	                    "The claim is deferred until " + claim.getDeferredUntil() + " and cannot be settled before then.");
120	        }
121	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
122	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
123	                    "The user who opened a claim cannot settle it.");
124	        }
125	        Person person = person(sheetId, claim.getPersonId());
126	        // Worked out while the claim is still open: settling freezes the due, its late charge included.
127	        BigDecimal dueNow = next == ClaimStatus.SETTLED ? due(sheetId, person, claim) : null;
128	        if (next == ClaimStatus.SETTLED && isAboveClerkLimit(sheetId, user, dueNow)) next = ClaimStatus.PENDING;
129	        Rollup.Snapshot before = rollup.snapshot(sheetId);
130	        String number = next == ClaimStatus.OPEN ? nextNumber(sheetId, claim) : claim.getNumber();
131	        claim.setStatus(next);
132	        if (next == ClaimStatus.OPEN) claim.setOpenedBy(user);
133	        // A voided claim keeps its number, which is never given to another claim.
134	        claim.setNumber(number);
135	        if (next == ClaimStatus.SETTLED) claim.setSettledDue(dueNow);
136	        logStatus(sheetId, user, person, claim);
137	        Claim saved = claims.saveAndFlush(claim);
138	        String event = EVENTS.get(next);
139	        if (next == ClaimStatus.SETTLED) {
140	            recordChange(event, user, person, saved, number, " due=" + text(saved.getSettledDue()));
141	        } else {
142	            recordChange(event, user, person, saved, number, "");
143	        }
144	        rollup.recordChanges(user, before);
145	        return saved;
146	    }
