148	    /** Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches it the
149	     *  claim counts in no total, is not overdue, cannot be settled and no statement binds it. Refused for
150	     *  a claim that is not OPEN, a date not after today, and a claim dated inside a closed period. */
151	    @Transactional
152	    public Claim defer(String sheetId, String user, long id, LocalDate until) {
153	        Claim claim = claims.findForUpdate(id, sheetId)
154	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
155	        refuseIfClosed(sheetId, claim.getDate());
156	        if (claim.getStatus() != ClaimStatus.OPEN) {
157	            throw new ResponseStatusException(HttpStatus.CONFLICT,
158	                    "A " + claim.getStatus() + " claim cannot be deferred; only an OPEN one can.");
159	        }
160	        if (!until.isAfter(sheets.today(sheetId))) {
161	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
162	                    "A claim can only be deferred to a date after the sheet's today.");
163	        }
164	        Person person = person(sheetId, claim.getPersonId());
165	        Rollup.Snapshot before = rollup.snapshot(sheetId);
166	        claim.deferUntil(until);
167	        Claim saved = claims.saveAndFlush(claim);
168	        recordChange("CLAIM_DEFERRED", user, person, saved, saved.getNumber(), " until=" + until);
169	        rollup.recordChanges(user, before);
170	        return saved;
171	    }
