173	    /** Move a DRAFT, OPEN or PENDING claim to another person on the sheet, as their newest claim. It
174	     *  keeps its number and date and loses any figure a statement bound it to (it is live again until
175	     *  its new person's next statement). Refused unless the user is a steward of the sheet, and for a
176	     *  settled or voided claim, a claim dated inside a closed period, a move to the claim's own person,
177	     *  or to a person retired by the claim's date. */
178	    @Transactional
179	    public Claim reassign(String sheetId, String user, long id, long toPersonId) {
180	        Claim claim = claims.findForUpdate(id, sheetId)
181	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
182	        refuseIfClosed(sheetId, claim.getDate());
183	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
184	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward moves a claim to another person.");
185	        }
186	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
187	            throw new ResponseStatusException(HttpStatus.CONFLICT,
188	                    "A " + claim.getStatus() + " claim cannot be moved to another person.");
189	        }
190	        Person from = person(sheetId, claim.getPersonId());
191	        Person to = person(sheetId, toPersonId);
192	        if (from.getId().equals(to.getId())) {
193	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already " + to.getName() + "'s.");
194	        }
195	        refuseIfRetired(to, claim.getDate());
196	        Rollup.Snapshot before = rollup.snapshot(sheetId);
197	        claim.moveTo(to.getId(), claims.lastListed(sheetId) + 1);
198	        Claim saved = claims.saveAndFlush(claim);
199	        recordChange("CLAIM_REASSIGNED", user, to, saved, saved.getNumber(),
200	                " from=" + from.getName() + " to=" + to.getName());
201	        rollup.recordChanges(user, before);
202	        return saved;
203	    }
