205	    /** Approve a PENDING claim: it is SETTLED, its due (its live figure and any late charge) frozen
206	     *  now. Refused unless the user is a steward of the sheet other than the one who opened it. */
207	    @Transactional
208	    public Claim approve(String sheetId, String user, long id) {
209	        Claim claim = pending(sheetId, user, id);
210	        if (user.equals(claim.getOpenedBy())) {
211	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
212	                    "The user who opened a claim cannot approve it.");
213	        }
214	        Person person = person(sheetId, claim.getPersonId());
215	        BigDecimal dueNow = due(sheetId, person, claim);
216	        Rollup.Snapshot before = rollup.snapshot(sheetId);
217	        claim.setStatus(ClaimStatus.SETTLED);
218	        claim.setSettledDue(dueNow);
219	        logStatus(sheetId, user, person, claim);
220	        Claim saved = claims.saveAndFlush(claim);
221	        recordChange("CLAIM_APPROVED", user, person, saved, saved.getNumber(), " due=" + text(saved.getSettledDue()));
222	        rollup.recordChanges(user, before);
223	        return saved;
224	    }
