226	    /** Re-settle a SETTLED claim: its due is frozen again at what it would be today as an open claim
227	     *  bound by no statement (today's rates, grades, floor and late charge). Refused unless the user is
228	     *  a steward of the sheet, and for a claim that is not SETTLED or is dated inside a closed period. */
229	    @Transactional
230	    public Claim resettle(String sheetId, String user, long id) {
231	        Claim claim = claims.findForUpdate(id, sheetId)
232	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
233	        refuseIfClosed(sheetId, claim.getDate());
234	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
235	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward re-settles a claim.");
236	        }
237	        if (claim.getStatus() != ClaimStatus.SETTLED) {
238	            throw new ResponseStatusException(HttpStatus.CONFLICT,
239	                    "A " + claim.getStatus() + " claim cannot be re-settled; only a SETTLED one can.");
240	        }
241	        Person person = person(sheetId, claim.getPersonId());
242	        BigDecimal old = claim.getSettledDue();
243	        BigDecimal dueNow = LateCharge.dueAsOpen(claim, dueNow(sheetId, person, claim), sheets.today(sheetId),
244	                settings.latePct(sheetId, claim.getDate()), rounding(sheetId, claim));
245	        Rollup.Snapshot before = rollup.snapshot(sheetId);
246	        claim.setSettledDue(dueNow);
247	        logStatus(sheetId, user, person, claim);
248	        Claim saved = claims.saveAndFlush(claim);
249	        recordChange("CLAIM_RESETTLED", user, person, saved, saved.getNumber(),
250	                " old=" + text(old) + " new=" + text(saved.getSettledDue()));
251	        rollup.recordChanges(user, before);
252	        return saved;
253	    }
