255	    /** Reject a PENDING claim for a reason: it is OPEN again, bound again by its person's last
256	     *  statement if that statement bound it. Refused unless the user is a steward of the sheet. */
257	    @Transactional
258	    public Claim reject(String sheetId, String user, long id, String reason) {
259	        Claim claim = pending(sheetId, user, id);
260	        Person person = person(sheetId, claim.getPersonId());
261	        Rollup.Snapshot before = rollup.snapshot(sheetId);
262	        claim.setStatus(ClaimStatus.OPEN);
263	        logStatus(sheetId, user, person, claim);
264	        Claim saved = claims.saveAndFlush(claim);
265	        recordChange("CLAIM_REJECTED", user, person, saved, saved.getNumber(), " reason=" + reason);
266	        rollup.recordChanges(user, before);
267	        return saved;
268	    }
