270	    /** The PENDING claim a steward approves or rejects, locked; refused when it is not PENDING, is
271	     *  dated inside a closed period, or the user is not a steward of the sheet. */
272	    private Claim pending(String sheetId, String user, long id) {
273	        Claim claim = claims.findForUpdate(id, sheetId)
274	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
275	        refuseIfClosed(sheetId, claim.getDate());
276	        if (claim.getStatus() != ClaimStatus.PENDING) {
277	            throw new ResponseStatusException(HttpStatus.CONFLICT,
278	                    "A " + claim.getStatus() + " claim is not waiting for approval.");
279	        }
280	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
281	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward approves or rejects a claim.");
282	        }
283	        return claim;
284	    }
