286	    private static final Map<ClaimStatus, String> EVENTS = Map.of(
287	            ClaimStatus.OPEN, "CLAIM_OPENED", ClaimStatus.PENDING, "CLAIM_PENDING",
288	            ClaimStatus.SETTLED, "CLAIM_SETTLED", ClaimStatus.VOID, "CLAIM_VOIDED");
289	
290	    private static String text(BigDecimal due) {
291	        return due == null ? "n/a" : due.toPlainString();
292	    }
