294	    /** The number a claim takes as it is opened: while the sheet's period numbering is in force (its
295	     *  today on or after the setting's date), the next of the claim's period, <period name>-<n>, or of
296	     *  claims in no period, X-<n>; otherwise the sheet's next sheet-wide number. */
297	    private String nextNumber(String sheetId, Claim claim) {
298	        LocalDate from = settings.periodNumberingFrom(sheetId);
299	        if (from == null || sheets.today(sheetId).isBefore(from)) {
300	            return Integer.toString(sheets.nextClaimNumber(sheetId));
301	        }
302	        Period period = periods.findBySheetIdOrderByFromAsc(sheetId).stream()
303	                .filter((p) -> p.contains(claim.getDate())).findFirst().orElse(null);
304	        if (period == null) return "X-" + sheets.nextSequenceNumber(sheetId, "none");
305	        return period.getName() + "-" + sheets.nextSequenceNumber(sheetId, "period:" + period.getId());
306	    }
