308	    /** Whether the user is a clerk settling a claim whose due is above the sheet's clerk limit. */
309	    private boolean isAboveClerkLimit(String sheetId, String user, BigDecimal due) {
310	        if (due == null || settings.roleOf(sheetId, user) == Role.STEWARD) return false;
311	        BigDecimal limit = settings.clerkLimit(sheetId);
312	        return limit != null && due.compareTo(limit) > 0;
313	    }
