315	    /** Refuse a change to a claim dated inside a closed period. The sheet is locked first, as closing
316	     *  a period locks it, so a claim cannot change in a period while it is being closed. */
317	    private void refuseIfClosed(String sheetId, LocalDate date) {
318	        sheetRows.findForUpdate(sheetId);
319	        if (periods.isClosedOn(sheetId, date)) {
320	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is dated inside a closed period.");
321	        }
322	    }
