324	    /** Refuse a correction (a negative amount) unless it names, by number, a settled claim of the same person. */
325	    private void refuseIfNotCorrecting(String sheetId, long personId, BigDecimal amount, String corrects) {
326	        if (amount.signum() >= 0) return;
327	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
328	                .filter(c -> c.getStatus() == ClaimStatus.SETTLED).isPresent();
329	        if (!settled) {
330	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
331	                    "A negative amount must name, by number, a settled claim of the same person that it corrects.");
332	        }
333	    }
