335	    /** Refuse a claim dated after its person's retirement date. */
336	    private static void refuseIfRetired(Person person, LocalDate date) {
337	        if (person.isRetiredOn(date)) {
338	            throw new ResponseStatusException(HttpStatus.CONFLICT,
339	                    "The claim is dated after " + person.getName() + " retired.");
340	        }
341	    }
