348	    /** What is due on the claim now: its figure with the late charge on top while it is open and
349	     *  overdue (the charge is never bound by a statement); null when the figure is n/a. */
350	    public BigDecimal due(String sheetId, Person person, Claim claim) {
351	        return LateCharge.dueOf(claim, figure(sheetId, person, claim), sheets.today(sheetId),
352	                settings.latePct(sheetId, claim.getDate()), rounding(sheetId, claim));
353	    }
354	
355	    /** The figure under the claim's due, before any late charge: the due fixed when it was settled, else the figure
356	     *  its person's last statement bound it to (unless it is PENDING, which no statement binds), else its live due;
357	     *  null when that is n/a. */
358	    public BigDecimal figure(String sheetId, Person person, Claim claim) {
359	        if (claim.getSettledDue() != null) return claim.getSettledDue();
360	        if (claim.isBound()) return claim.getStatedDue();
361	        return dueNow(sheetId, person, claim);
362	    }
363	
364	    /** What is due on the claim now at the rate in force on the claim's date of its person's grade in
365	     *  force on that date, rounded
366	     *  as the claim's {@link Rounding} decides and at least the sheet's floor (a correction has no floor); null when no rate of the
367	     *  grade applies by then. */
368	    private BigDecimal dueNow(String sheetId, Person person, Claim claim) {
369	        Rate rate = rates.inForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate());
370	        if (rate == null) return null;
371	        BigDecimal due = claim.getAmount().multiply(rate.getPct()).divide(BigDecimal.valueOf(100), 2,
372	                rounding(sheetId, claim));
373	        return claim.isCorrection() ? due : due.max(settings.floor(sheetId, claim.getDate()));
374	    }
375	
376	    /** How the claim's live figures round under the sheet's policy date: by the date of the claim a
377	     *  correction corrects, else by its own. */
378	    private RoundingMode rounding(String sheetId, Claim claim) {
379	        Claim corrected = claim.isCorrection() && claim.getCorrects() != null
380	                ? claims.findBySheetIdAndPersonIdAndNumber(sheetId, claim.getPersonId(), claim.getCorrects()).orElse(null)
381	                : null;
382	        return Rounding.of(Rounding.dateOf(claim, corrected),
383	                Rounding.policyDate(settings.policyDate(sheetId), sheets.today(sheetId)));
384	    }
385	
386	    /** Log the status the claim has just taken, with its due as worked out now. */
387	    private void logStatus(String sheetId, String user, Person person, Claim claim) {
388	        claim.logStatus(user, sheets.today(sheetId), due(sheetId, person, claim));
389	    }
390	
391	    private void recordChange(String event, String user, Person person, Claim claim) {
392	        recordChange(event, user, person, claim, claim.getNumber(), "");
393	    }
394	
395	    /** The claim's audit line; a claim with a number carries it, then any extra fields. */
396	    private void recordChange(String event, String user, Person person, Claim claim, String number, String extra) {
397	        audit.recordOnCommit(event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
398	                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate()
399	                + (number == null ? "" : " number=" + number) + extra);
400	    }
