402	    private LocalDate dateOr(String sheetId, LocalDate date) {
403	        return date != null ? date : sheets.today(sheetId);
404	    }
405	
406	    private static String noteOf(String note) {
407	        return note == null ? "" : note.trim();
408	    }
409	}
